sp_widget.client_script:
api.controller = function($window) {

    var c = this;


    /* =========================================================
       CAMPUS360 SIDEBAR / UI
       ========================================================= */

    c.sidebarOpen = true;

    c.pageRefreshing = false;


    /*
     * ============================================================
     * TOGGLE SIDEBAR
     * ============================================================
     */

    c.toggleSidebar = function() {

        c.sidebarOpen =
            !c.sidebarOpen;

    };


    /*
     * ============================================================
     * STUDENT INITIALS
     * ============================================================
     */

    c.getStudentInitials = function() {

        var name =
            c.data &&
            c.data.student &&
            c.data.student.name
                ? String(
                    c.data.student.name
                  )
                : 'Test Student Campus360';


        var parts =
            name
                .trim()
                .split(/\s+/);


        if (!parts.length) {

            return 'TC';

        }


        if (parts.length === 1) {

            return parts[0]
                .substring(0, 2)
                .toUpperCase();

        }


        return (
            parts[0].charAt(0) +
            parts[
                parts.length - 1
            ].charAt(0)
        ).toUpperCase();

    };


    /*
     * ============================================================
     * CAMPUS360 PAGE NAVIGATION
     * ============================================================
     */

    c.navigate = function(pageId) {

        if (!pageId) {

            return;

        }


        var studentId =
            c.data &&
            c.data.student &&
            c.data.student.studentId
                ? c.data.student.studentId
                : '';


        var url =
            '?id=' +
            encodeURIComponent(
                pageId
            );


        if (studentId) {

            url +=
                '&student=' +
                encodeURIComponent(
                    studentId
                );

        }


        $window.location.href =
            url;

    };


    /*
     * ============================================================
     * REFRESH PAGE
     * ============================================================
     */

    c.refreshPage = function() {

        if (c.pageRefreshing) {

            return;

        }


        c.pageRefreshing = true;


        c.server.get({

            action: 'load',

            selectedDate:
                c.formatDateForServer(
                    c.selectedDate
                )

        }).then(function(response) {

            c.data =
                response.data;


            c.selectedType =
                '';


            c.selectedSlot =
                null;


            c.pageRefreshing =
                false;


        }, function() {

            c.pageRefreshing =
                false;

        });

    };


    /* =========================================================
       BOOKING STATE
       ========================================================= */

    c.step = 1;

    c.selectedDate = null;

    c.selectedType = '';

    c.selectedSlot = null;

    c.submitting = false;

    c.pollTimer = null;


    /*
     * ============================================================
     * DATE HELPERS
     * ============================================================
     */

    c.formatDateForServer = function(d) {

        if (!d) {

            return '';

        }


        if (
            Object.prototype.toString.call(d) !==
            '[object Date]'
        ) {

            return String(d);

        }


        if (
            isNaN(
                d.getTime()
            )
        ) {

            return '';

        }


        var year =
            d.getFullYear();


        var month =
            d.getMonth() + 1;


        var day =
            d.getDate();


        if (month < 10) {

            month =
                '0' + month;

        }


        if (day < 10) {

            day =
                '0' + day;

        }


        return (
            year +
            '-' +
            month +
            '-' +
            day
        );

    };


    /*
     * ============================================================
     * TODAY
     * ============================================================
     */

    c.makeTodayDate = function() {

        var now =
            new Date();


        return new Date(

            now.getFullYear(),

            now.getMonth(),

            now.getDate()

        );

    };


    /*
     * ============================================================
     * INITIALIZATION
     * ============================================================
     */

    c.selectedDate =
        c.makeTodayDate();


    c.minDate =
        c.formatDateForServer(
            c.selectedDate
        );


    /*
     * ============================================================
     * DATE CHANGE
     * ============================================================
     */

    c.onDateChanged = function() {

        c.data.error = '';

        c.data.success = '';

        c.selectedType = '';

        c.selectedSlot = null;

        c.data.slots = [];


        var dateString =
            c.formatDateForServer(
                c.selectedDate
            );


        if (!dateString) {

            c.data.error =
                'Please select a valid interview date.';

            return;

        }


        c.server.get({

            action: 'load',

            selectedDate:
                dateString

        }).then(function(response) {

            c.data =
                response.data;


            c.selectedType =
                '';


            c.selectedSlot =
                null;

        });

    };


    /*
     * ============================================================
     * SELECT INTERVIEW TYPE
     * ============================================================
     */

    c.selectType = function(type) {

        if (
            !type ||
            type.count === 0
        ) {

            return;

        }


        c.selectedType =
            type.value;


        c.selectedSlot =
            null;


        c.data.error = '';

        c.data.success = '';

    };


    /*
     * ============================================================
     * FILTER SLOTS
     * ============================================================
     */

    c.getFilteredSlots = function() {

        if (
            !c.data ||
            !c.data.slots
        ) {

            return [];

        }


        if (!c.selectedType) {

            return [];

        }


        var result = [];


        for (
            var i = 0;
            i < c.data.slots.length;
            i++
        ) {

            var slot =
                c.data.slots[i];


            if (
                String(
                    slot.interviewType
                ) ===
                String(
                    c.selectedType
                )
            ) {

                result.push(
                    slot
                );

            }

        }


        return result;

    };


    /*
     * ============================================================
     * ANGULAR PROPERTY
     * ============================================================
     */

    Object.defineProperty(
        c,
        'filteredSlots',
        {

            get: function() {

                return c.getFilteredSlots();

            }

        }
    );


    /*
     * ============================================================
     * SELECT SLOT
     * ============================================================
     */

    c.selectSlot = function(slot) {

        if (!slot) {

            return;

        }


        c.selectedSlot =
            slot;


        c.data.error = '';

        c.data.success = '';

    };


    /*
     * ============================================================
     * SUBMIT REQUEST
     * ============================================================
     */

    c.submitRequest = function() {

        c.data.error = '';

        c.data.success = '';


        if (!c.selectedDate) {

            c.data.error =
                'Please select an interview date.';

            return;

        }


        if (!c.selectedType) {

            c.data.error =
                'Please select an interview type.';

            return;

        }


        if (!c.selectedSlot) {

            c.data.error =
                'Please select an available time slot.';

            return;

        }


        var dateString =
            c.formatDateForServer(
                c.selectedDate
            );


        if (!dateString) {

            c.data.error =
                'The selected date is invalid.';

            return;

        }


        if (
            !c.selectedSlot.availabilityIds ||
            c.selectedSlot.availabilityIds.length === 0
        ) {

            c.data.error =
                'The selected availability record could not be identified. Please refresh the date and select the slot again.';

            return;

        }


        var selectedAvailabilityId =
            String(
                c.selectedSlot
                    .availabilityIds[0]
            );


        c.submitting =
            true;


        c.server.get({

            action: 'submit',

            selectedDate:
                dateString,

            selectedAvailabilityId:
                selectedAvailabilityId,

            notes:
                'Mock interview request for ' +
                String(
                    c.selectedSlot
                        .interviewTypeLabel ||
                    ''
                ) +
                (
                    c.selectedSlot
                        .skillAreaLabel
                        ? ' - ' +
                          c.selectedSlot
                              .skillAreaLabel
                        : ''
                )

        }).then(function(response) {

            c.submitting =
                false;


            c.data =
                response.data;


            if (c.data.error) {

                c.step =
                    1;

                return;

            }


            if (
                c.data.currentRequest
            ) {

                c.step =
                    2;


                c.startPolling();

            }


        }, function() {

            c.submitting =
                false;


            c.data.error =
                'Unable to send the mock interview request. Please try again.';

        });

    };


    /*
     * ============================================================
     * POLLING
     * ============================================================
     */

    c.startPolling = function() {

        if (c.pollTimer) {

            clearTimeout(
                c.pollTimer
            );

        }


        c.pollTimer =
            setTimeout(

                function() {

                    c.refreshRequest(
                        true
                    );

                },

                15000

            );

    };


    /*
     * ============================================================
     * REFRESH REQUEST
     * ============================================================
     */

    c.refreshRequest = function(
        silent
    ) {

        if (
            !c.data.currentRequest ||
            !c.data.currentRequest.requestId
        ) {

            return;

        }


        c.server.get({

            action: 'poll',

            requestId:
                c.data.currentRequest
                    .requestId

        }).then(function(response) {

            c.data =
                response.data;


            /*
             * TRAINER ACCEPTED
             */

            if (
                c.data.currentRequest &&
                String(
                    c.data.currentRequest.status
                ).toLowerCase() ===
                'accepted'
            ) {

                c.step =
                    3;


                if (c.pollTimer) {

                    clearTimeout(
                        c.pollTimer
                    );

                }


                return;

            }


            /*
             * STILL WAITING
             */

            if (
                c.data.currentRequest
            ) {

                c.step =
                    2;


                c.startPolling();

            }


        }, function() {

            if (!silent) {

                c.data.error =
                    'Unable to refresh request status.';

            }

        });

    };


    /*
     * ============================================================
     * OPEN BOOKED SLOT DETAILS
     * ============================================================
     */

    c.openBookedSlot = function(slot) {

        if (!slot) {
            return;
        }


        if (c.pollTimer) {

            clearTimeout(
                c.pollTimer
            );

            c.pollTimer =
                null;

        }


        c.data.error = '';

        c.data.success = '';

        c.data.currentRequest =
            slot;

        c.step =
            3;

    };


    /*
     * ============================================================
     * BOOK ANOTHER
     * ============================================================
     */

    c.backToBooking = function() {

        if (c.pollTimer) {

            clearTimeout(
                c.pollTimer
            );

        }


        c.step =
            1;


        c.selectedType =
            '';


        c.selectedSlot =
            null;


        c.data.error =
            '';


        c.data.success =
            '';


        c.onDateChanged();

    };


    /*
     * ============================================================
     * CLEANUP
     * ============================================================
     */

    c.$onDestroy = function() {

        if (c.pollTimer) {

            clearTimeout(
                c.pollTimer
            );

        }

    };


    /*
     * ============================================================
     * FIRST SERVER LOAD
     * ============================================================
     */

    c.server.get({

        action: 'load',

        selectedDate:
            c.formatDateForServer(
                c.selectedDate
            )

    }).then(function(response) {

        c.data =
            response.data;


        c.selectedType =
            '';


        c.selectedSlot =
            null;

    });

};

sp_widget.css:
/* =========================================================
   CAMPUS360 MOCK INTERVIEW SLOT BOOKING
   FINAL STUDENT PORTAL STYLE
   ========================================================= */


/* =========================================================
   SERVICENOW HEADER RESET
   ========================================================= */

body:has(.campus360-booking) #sp-header,
body:has(.campus360-booking) .sp-header,
body:has(.campus360-booking) .sp-navbar,
body:has(.campus360-booking) .navbar.sp-navbar,
body:has(.campus360-booking) #sp-nav-bar,
body:has(.campus360-booking) .sp-nav-bar,
body:has(.campus360-booking) header#sp-header,
body:has(.campus360-booking) header.sp-header {

    display: none !important;

}


body:has(.campus360-booking) #sp-page,
body:has(.campus360-booking) #sp-main {

    margin-top: 0 !important;

    padding-top: 0 !important;

}


/* ServiceNow widget wrappers */

.well:has(.campus360-booking),
.panel:has(.campus360-booking) {

    width: 100% !important;

    max-width: none !important;

    margin: 0 !important;

    padding: 0 !important;

    border: 0 !important;

    background: transparent !important;

    box-shadow: none !important;

}


.panel:has(.campus360-booking) .panel-body {

    width: 100% !important;

    margin: 0 !important;

    padding: 0 !important;

}


.row:has(.campus360-booking) {

    margin-left: 0 !important;

    margin-right: 0 !important;

}


/* =========================================================
   ROOT
   ========================================================= */

.campus360-booking {

    position: fixed !important;

    inset: 0 !important;

    width: 100vw !important;

    height: 100vh !important;

    min-height: 100vh !important;

    max-width: 100vw !important;

    max-height: 100vh !important;

    margin: 0 !important;

    padding: 0 !important;

    display: block !important;

    overflow: hidden !important;

    background:
        linear-gradient(
            135deg,
            #f1f6fc 0%,
            #f7f4ff 50%,
            #f0f8f6 100%
        );

    color: #142840;

    font-family:
        "Inter",
        "Segoe UI",
        Arial,
        sans-serif;

    z-index: 999999 !important;

}


.campus360-booking,
.campus360-booking *,
.campus360-booking *::before,
.campus360-booking *::after {

    box-sizing: border-box;

}


/* =========================================================
   LEFT SIDEBAR
   DARK PURPLE
   ========================================================= */

.c360-left-sidebar {

    position: absolute !important;

    left: 0;

    top: 0;

    bottom: 0;

    width: 285px !important;

    min-width: 285px !important;

    max-width: 285px !important;

    height: 100vh !important;

    min-height: 100vh !important;

    display: flex;

    flex-direction: column;

    overflow: hidden;

    background:
        linear-gradient(
            180deg,
            #130d2f 0%,
            #160d38 48%,
            #100a29 100%
        ) !important;

    border-right:
        1px solid #2d2157 !important;

    box-shadow:
        4px 0 18px
        rgba(25,10,60,.20);

    z-index: 100;

    transition:
        transform .25s ease;

}


.campus360-booking.sidebar-closed
.c360-left-sidebar {

    transform:
        translateX(-105%);

}


/* =========================================================
   SIDEBAR BRAND
   ========================================================= */

.c360-sidebar-brand {

    height: 88px;

    min-height: 88px;

    flex: 0 0 88px;

    padding:
        0
        20px;

    display: flex;

    align-items: center;

    gap: 12px;

    border-bottom:
        1px
        solid
        #2d2157;

}


.c360-brand-logo {

    width: 48px;

    height: 48px;

    min-width: 48px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 13px;

    background:
        linear-gradient(
            135deg,
            #7c3aed,
            #9333ea
        );

    color: #ffffff;

    font-size: 23px;

    font-weight: 900;

    box-shadow:
        0
        7px
        18px
        rgba(124,58,237,.34);

}


.c360-brand-name {

    min-width: 0;

}


.c360-brand-name strong {

    display: block;

    color: #ffffff;

    font-size: 20px;

    line-height: 1;

    font-weight: 900;

}


.c360-brand-name span {

    display: block;

    margin-top: 5px;

    color: #c4b5fd;

    font-size: 10px;

    font-weight: 850;

    letter-spacing: .45px;

}


/* =========================================================
   STUDENT CARD
   ========================================================= */

.c360-sidebar-student {

    margin:
        18px
        13px
        10px;

    padding: 12px;

    min-height: 67px;

    display: flex;

    align-items: center;

    gap: 10px;

    border:
        1px
        solid
        #3a2d68;

    border-radius: 14px;

    background: #1d1440;

    color: inherit !important;

    text-decoration: none !important;

}


.c360-sidebar-student:hover {

    border-color: #6246a8;

    background: #24174d;

    box-shadow:
        0
        6px
        16px
        rgba(124,58,237,.14);

}


.c360-sidebar-avatar {

    width: 43px;

    height: 43px;

    min-width: 43px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    background:
        linear-gradient(
            135deg,
            #7659f4,
            #6654eb
        );

    color: #ffffff;

    font-size: 11px;

    font-weight: 900;

}


.c360-sidebar-student-info {

    min-width: 0;

    flex: 1;

}


.c360-sidebar-student-info strong {

    display: block;

    max-width: 190px;

    overflow: hidden;

    white-space: nowrap;

    text-overflow: ellipsis;

    color: #ffffff;

    font-size: 13px;

    font-weight: 900;

}


.c360-sidebar-student-info span {

    display: block;

    margin-top: 3px;

    color: #aaa0c7;

    font-size: 10px;

    font-weight: 600;

}


.c360-student-arrow {

    color: #a99fc7;

    font-size: 21px;

}


/* =========================================================
   NAV
   ========================================================= */

.c360-sidebar-nav {

    flex:
        1
        1
        auto;

    min-height: 0;

    padding:
        2px
        8px
        12px;

    overflow-y: auto;

    overflow-x: hidden;

    scrollbar-width: none;

    -ms-overflow-style: none;

}


.c360-sidebar-nav::-webkit-scrollbar {

    width: 0 !important;

    height: 0 !important;

    display: none !important;

}


.c360-nav-group {

    margin-bottom: 4px;

}


.c360-nav-heading {

    padding:
        17px
        9px
        8px;

    color: #8f84ae;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: .11em;

}


.c360-nav-link {

    position: relative;

    width: 100%;

    min-height: 46px;

    margin:
        3px
        0;

    padding:
        9px
        12px;

    display: flex;

    align-items: center;

    gap: 12px;

    border: 0;

    border-radius: 11px;

    background: transparent;

    color: #d8d0eb !important;

    font-family: inherit;

    font-size: 14px;

    font-weight: 750;

    text-decoration: none !important;

    cursor: pointer;

    transition:
        background .18s ease,
        color .18s ease,
        transform .18s ease;

}


.c360-nav-link:hover {

    color: #ffffff !important;

    background:
        rgba(124,58,237,.18);

    transform:
        translateX(2px);

}


.c360-nav-link.active {

    color: #ffffff !important;

    background:
        linear-gradient(
            90deg,
            #7c3aed 0%,
            #8b3ff2 100%
        );

    font-weight: 900;

    box-shadow:
        0
        5px
        14px
        rgba(124,58,237,.24);

}


.c360-nav-link.active::before {

    content: "";

    position: absolute;

    left: 0;

    top: 8px;

    bottom: 8px;

    width: 4px;

    border-radius:
        0
        4px
        4px
        0;

    background: #ffffff;

}


.c360-nav-icon {

    width: 24px;

    min-width: 24px;

    height: 24px;

    display: flex;

    align-items: center;

    justify-content: center;

    color: #a99fc7;

}


.c360-nav-icon .fa {

    font-size: 16px;

}


.c360-nav-link:hover
.c360-nav-icon,
.c360-nav-link.active
.c360-nav-icon {

    color: #ffffff;

}


.c360-nav-link > span:last-child {

    min-width: 0;

    flex: 1;

    white-space: nowrap;

}


/* =========================================================
   SIDEBAR FOOTER
   ========================================================= */

.c360-sidebar-footer {

    flex:
        0
        0
        auto;

    margin:
        0
        12px
        12px;

    padding:
        12px;

    border:
        1px
        solid
        #3a2d68;

    border-radius: 12px;

    background: #1a1138;

}


.c360-footer-title {

    color: #9d91b8;

    font-size: 9px;

    font-weight: 900;

    letter-spacing: 1px;

}


.c360-readiness-track {

    width: 100%;

    height: 7px;

    margin-top: 9px;

    overflow: hidden;

    border-radius: 10px;

    background: #302454;

}


.c360-readiness-fill {

    height: 100%;

    border-radius: inherit;

    background:
        linear-gradient(
            90deg,
            #7c3aed,
            #a855f7
        );

}


.c360-readiness-text {

    margin-top: 6px;

    color: #9d91b8;

    font-size: 10px;

    font-weight: 700;

}


/* =========================================================
   MAIN PAGE
   ========================================================= */

.c360-right-page {

    position: absolute !important;

    top: 0;

    right: 0;

    bottom: 0;

    left: 285px;

    width: auto !important;

    height: 100vh !important;

    min-width: 0 !important;

    min-height: 100vh !important;

    overflow-x: hidden !important;

    overflow-y: auto !important;

    background:
        linear-gradient(
            135deg,
            #f1f6fc 0%,
            #f7f4ff 50%,
            #f0f8f6 100%
        );

    transition:
        left .25s ease;

    scrollbar-width: none;

    -ms-overflow-style: none;

}


.c360-right-page::-webkit-scrollbar {

    width: 0 !important;

    height: 0 !important;

    display: none !important;

}


.campus360-booking.sidebar-closed
.c360-right-page {

    left: 0;

}


/* =========================================================
   TOP BAR
   WHITE
   ========================================================= */

.c360-topbar {

    position: sticky;

    top: 0;

    z-index: 2000;

    width: 100%;

    height: 78px;

    min-height: 78px;

    padding:
        0
        24px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    background: #ffffff !important;

    border-bottom:
        1px
        solid
        #dfe5ee;

    box-shadow:
        0
        2px
        10px
        rgba(20,39,60,.035);

}


/* =========================================================
   TOP LEFT
   ========================================================= */

.c360-topbar-left {

    min-width: 0;

    display: flex;

    align-items: center;

    gap: 13px;

}


/* =========================================================
   HAMBURGER
   ========================================================= */

.c360-menu-button {

    width: 42px;

    height: 42px;

    min-width: 42px;

    padding: 0;

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    gap: 4px;

    border:
        1px
        solid
        #dce2ea;

    border-radius: 10px;

    background: #ffffff;

    cursor: pointer;

}


.c360-menu-button:hover {

    background: #f5f2ff;

    border-color: #bdb3f5;

}


.c360-menu-button span {

    display: block;

    width: 19px;

    height: 2px;

    border-radius: 3px;

    background: #5146e5;

}


/* =========================================================
   PAGE HEADING
   ========================================================= */

.c360-page-heading {

    min-width: 220px;

    display: flex;

    flex-direction: column;

}


.c360-page-heading span {

    color: #5146e5;

    font-size: 9px;

    font-weight: 950;

    letter-spacing: 1.6px;

}


.c360-page-heading strong {

    margin-top: 5px;

    color: #172a33;

    font-size: 17px;

    line-height: 1.1;

    font-weight: 900;

}


/* =========================================================
   TOP RIGHT
   ========================================================= */

.c360-topbar-right {

    margin-left: auto;

    display: flex;

    align-items: center;

    gap: 9px;

}


/* =========================================================
   TOP ICONS
   ========================================================= */

.c360-top-icon {

    position: relative;

    width: 41px;

    height: 41px;

    min-width: 41px;

    padding: 0;

    display: flex;

    align-items: center;

    justify-content: center;

    border:
        1px
        solid
        #dce2ea;

    border-radius: 10px;

    background: #ffffff;

    color: #5c667a;

    cursor: pointer;

    transition:
        background .18s ease,
        color .18s ease,
        border-color .18s ease;

}


.c360-top-icon:hover {

    color: #5146e5;

    background: #f6f3ff;

    border-color: #c7bdf5;

}


.c360-top-icon svg {

    width: 18px;

    height: 18px;

    fill: none;

    stroke: currentColor;

    stroke-width: 1.8;

    stroke-linecap: round;

    stroke-linejoin: round;

}


/* =========================================================
   NOTIFICATION
   ========================================================= */

.c360-notification-button {

    color: #5146e5;

}


.c360-notification-dot {

    position: absolute;

    top: 6px;

    right: 6px;

    width: 7px;

    height: 7px;

    border-radius: 50%;

    background: #ff4058;

    border:
        1.5px
        solid
        #ffffff;

}


/* =========================================================
   TOP PROFILE
   ========================================================= */

.c360-top-student {

    min-height: 45px;

    padding-left: 11px;

    display: flex;

    align-items: center;

    gap: 9px;

    border-left:
        1px
        solid
        #e2e6ee;

    color: inherit !important;

    text-decoration: none !important;

}


.c360-top-avatar {

    width: 39px;

    height: 39px;

    min-width: 39px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    background:
        linear-gradient(
            135deg,
            #7659f4,
            #6654eb
        );

    color: #ffffff;

    font-size: 11px;

    font-weight: 900;

}


.c360-top-student-info {

    min-width: 0;

    display: flex;

    flex-direction: column;

}


.c360-top-student-info strong {

    display: block;

    max-width: 210px;

    overflow: hidden;

    white-space: nowrap;

    text-overflow: ellipsis;

    color: #101828;

    font-size: 12px;

    line-height: 1.25;

    font-weight: 900;

}


.c360-top-student-info span {

    display: block;

    margin-top: 2px;

    color: #667085;

    font-size: 9px;

    font-weight: 600;

}


.c360-top-chevron {

    color: #667085;

    font-size: 13px;

}


/* =========================================================
   CONTENT
   ========================================================= */

.c360-page-content {

    width: 100%;

    min-width: 0;

    padding:
        24px
        14px
        45px;

}


/* =========================================================
   MOCK INTERVIEW SLOT BOOKING HERO
   SAME DARK PURPLE AS SIDEBAR
   ========================================================= */

.mi-hero {

    position: relative;

    z-index: 1;

    width: 100%;

    min-height: 170px;

    margin:
        0
        0
        20px;

    padding:
        28px
        38px;

    display: flex;

    align-items: center;

    overflow: hidden;

    border-radius: 18px;

    background:
        linear-gradient(
            180deg,
            #130d2f 0%,
            #160d38 48%,
            #100a29 100%
        ) !important;

    border:
        1px
        solid
        #2d2157 !important;

    color: #ffffff !important;

    box-shadow:
        0
        12px
        28px
        rgba(19,13,47,.22);

}


.mi-hero::after {

    content: "";

    position: absolute;

    width: 220px;

    height: 220px;

    right: -70px;

    top: -105px;

    border-radius: 50%;

    background:
        rgba(124,58,237,.10);

}


.mi-hero-icon {

    position: relative;

    z-index: 1;

    width: 52px;

    height: 52px;

    min-width: 52px;

    margin-right: 18px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 13px;

    background:
        rgba(124,58,237,.18);

    color: #c4b5fd !important;

    font-size: 23px;

}


.mi-hero-content {

    position: relative;

    z-index: 1;

    min-width: 0;

}


.mi-hero-eyebrow {

    margin-bottom: 7px;

    color: #c4b5fd !important;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 1.6px;

}


.mi-hero-content h1 {

    margin: 0;

    color: #ffffff !important;

    font-size: 34px;

    line-height: 1.12;

    font-weight: 900;

    letter-spacing: -.5px;

}


.mi-hero-content p {

    max-width: 900px;

    margin:
        9px
        0
        0;

    color: #d8d0eb !important;

    font-size: 13px;

    line-height: 1.6;

}


/* =========================================================
   ALERTS
   ========================================================= */

.mi-alert {

    width: 100%;

    margin-bottom: 15px;

    padding:
        12px
        15px;

    display: flex;

    align-items: center;

    gap: 8px;

    border-radius: 9px;

    font-size: 12px;

}


.mi-alert-error {

    background: #fff1f4;

    border:
        1px
        solid
        #f4c2d0;

    color: #b4234b;

}


.mi-alert-success {

    background: #edf9f1;

    border:
        1px
        solid
        #b9e3c6;

    color: #23723c;

}


/* =========================================================
   MAIN LAYOUT
   ========================================================= */

.mi-layout {

    width: 100%;

    min-width: 0;

    display: grid;

    grid-template-columns:
        minmax(0,1fr)
        305px;

    gap: 18px;

    align-items: start;

}


/* =========================================================
   MAIN CARD
   ========================================================= */

.mi-main-card {

    min-width: 0;

    width: 100%;

    padding: 26px;

    border:
        1px
        solid
        #dce5ee;

    border-radius: 16px;

    background: #ffffff;

    box-shadow:
        0
        7px
        24px
        rgba(28,89,131,.055);

}


/* =========================================================
   BOOKING HEADER
   ========================================================= */

.mi-section-top {

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 15px;

}


.mi-eyebrow {

    margin-bottom: 6px;

    color: #5146e5;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 1.7px;

}


.mi-section-top h2 {

    margin: 0;

    color: #112e4c;

    font-size: 22px;

    line-height: 1.2;

    font-weight: 850;

}


.mi-step-badge {

    flex-shrink: 0;

    padding:
        8px
        13px;

    border-radius: 18px;

    background: #efebff;

    color: #5146e5;

    font-size: 10px;

    font-weight: 850;

    white-space: nowrap;

}


.mi-divider {

    height: 1px;

    margin:
        18px
        0
        23px;

    background: #e2e8ef;

}


/* =========================================================
   FORM
   ========================================================= */

.mi-field-group {

    margin-bottom: 25px;

}


.mi-field-group > label {

    display: block;

    margin-bottom: 8px;

    color: #1d3957;

    font-size: 13px;

    font-weight: 850;

}


.mi-help {

    margin-top: 7px;

    color: #8290a1;

    font-size: 10px;

    line-height: 1.5;

}


.mi-help-top {

    margin-top: -1px;

    margin-bottom: 12px;

}


.mi-date-input {

    width: 100%;

    height: 48px;

    padding:
        0
        13px;

    border:
        1px
        solid
        #ccd8e6;

    border-radius: 10px;

    background: #ffffff;

    color: #263e59;

    font-size: 13px;

    outline: none;

}


.mi-date-input:focus {

    border-color: #6254ed;

    box-shadow:
        0
        0
        0
        3px
        rgba(98,84,237,.09);

}


/* =========================================================
   TYPE CARDS
   ========================================================= */

.mi-type-grid {

    display: grid;

    grid-template-columns:
        repeat(4,minmax(0,1fr));

    gap: 10px;

}


.mi-type-card {

    min-width: 0;

    min-height: 76px;

    padding: 13px;

    border:
        1px
        solid
        #dce4ed;

    border-radius: 11px;

    background: #ffffff;

    color: #3f5570;

    text-align: left;

    cursor: pointer;

    transition:
        border-color .16s ease,
        box-shadow .16s ease,
        transform .16s ease;

}


.mi-type-card:hover {

    border-color: #aaa0e9;

    box-shadow:
        0
        5px
        14px
        rgba(98,84,237,.09);

    transform:
        translateY(-1px);

}


.mi-type-card.selected {

    border:
        2px
        solid
        #6254ed;

    background:
        linear-gradient(
            135deg,
            #f5f2ff,
            #fbfaff
        );

    color: #5146e5;

}


.mi-type-card:disabled {

    opacity: .48;

    cursor: not-allowed;

    transform: none;

    background: #f7f9fb;

}


.mi-type-name {

    font-size: 12px;

    font-weight: 850;

}


.mi-type-card.selected
.mi-type-name {

    color: #5146e5;

}


.mi-type-count {

    margin-top: 7px;

    color: #6254ed;

    font-size: 9px;

    font-weight: 750;

}


.mi-type-count.muted {

    color: #9ba7b5;

}


/* =========================================================
   TIME CARDS
   ========================================================= */

.mi-time-grid {

    display: grid;

    grid-template-columns:
        repeat(2,minmax(0,1fr));

    gap: 11px;

}


.mi-time-card {

    min-width: 0;

    min-height: 93px;

    padding: 15px;

    border:
        1px
        solid
        #dce4ed;

    border-radius: 11px;

    background: #ffffff;

    text-align: left;

    cursor: pointer;

    transition:
        border-color .16s ease,
        box-shadow .16s ease,
        transform .16s ease;

}


.mi-time-card:hover {

    border-color: #159eae;

    box-shadow:
        0
        5px
        15px
        rgba(11,154,154,.08);

    transform:
        translateY(-1px);

}


.mi-time-card.selected {

    border:
        2px
        solid
        #0b9a9a;

    background:
        linear-gradient(
            135deg,
            #effcfc,
            #f8ffff
        );

}


.mi-time-title {

    margin-bottom: 7px;

    color: #087f93;

    font-size: 15px;

    font-weight: 900;

}


.mi-time-skill {

    margin-bottom: 9px;

    color: #61758c;

    font-size: 10px;

}


.mi-trainer-count {

    color: #8291a1;

    font-size: 9px;

}


.mi-trainer-count i {

    margin-right: 4px;

    color: #0b9a9a;

}


/* =========================================================
   EMPTY
   ========================================================= */

.mi-empty,
.mi-no-bookings {

    padding: 17px;

    border:
        1px
        solid
        #e2e8ef;

    border-radius: 10px;

    background: #f7f9fc;

    color: #8290a2;

    text-align: center;

    font-size: 10px;

}


/* =========================================================
   PRIMARY BUTTON
   ========================================================= */

.mi-submit-area {

    display: flex;

    justify-content: flex-end;

    margin-top: 5px;

}


.mi-primary-btn {

    min-width: 245px;

    min-height: 45px;

    padding:
        11px
        18px;

    border:
        1px
        solid
        #6254ed;

    border-radius: 9px;

    background:
        linear-gradient(
            135deg,
            #6254ed,
            #765ff0
        );

    color: #ffffff;

    font-size: 12px;

    font-weight: 850;

    box-shadow:
        0
        7px
        16px
        rgba(98,84,237,.20);

    cursor: pointer;

    transition:
        transform .16s ease,
        box-shadow .16s ease,
        filter .16s ease;

}


.mi-primary-btn:hover:not(:disabled) {

    filter: brightness(.97);

    transform:
        translateY(-1px);

    box-shadow:
        0
        9px
        18px
        rgba(98,84,237,.24);

}


.mi-primary-btn:disabled {

    opacity: .52;

    cursor: not-allowed;

    transform: none;

}


.mi-button-arrow {

    margin-left: 5px;

    font-size: 14px;

}


/* =========================================================
   SECONDARY BUTTON
   ========================================================= */

.mi-secondary-btn {

    min-height: 40px;

    margin-top: 16px;

    padding:
        10px
        16px;

    border:
        1px
        solid
        #c8bcf5;

    border-radius: 9px;

    background: #f5f2ff;

    color: #5146e5;

    font-size: 11px;

    font-weight: 850;

    cursor: pointer;

    transition:
        background .16s ease,
        border-color .16s ease,
        transform .16s ease;

}


.mi-secondary-btn:hover {

    background: #ece8ff;

    border-color: #b8aaf0;

    transform:
        translateY(-1px);

}


/* =========================================================
   STATUS BOX
   ========================================================= */

.mi-status-box {

    padding:
        22px
        15px
        27px;

    text-align: center;

}


.mi-status-icon {

    width: 58px;

    height: 58px;

    margin:
        0
        auto
        13px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    background: #fff5df;

    color: #d38a00;

    font-size: 23px;

}


.mi-status-icon.confirmed {

    background: #e7f9ed;

    color: #159447;

}


.mi-status-box h3 {

    margin:
        0
        0
        7px;

    color: #163451;

    font-size: 20px;

    font-weight: 850;

}


.mi-status-box p {

    margin: 0;

    color: #718196;

    font-size: 11px;

    line-height: 1.6;

}


/* =========================================================
   DETAILS
   ========================================================= */

.mi-detail-card {

    overflow: hidden;

    border:
        1px
        solid
        #e0e7ef;

    border-radius: 11px;

}


.mi-detail-row {

    min-height: 49px;

    padding:
        0
        15px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 15px;

    border-bottom:
        1px
        solid
        #edf1f5;

    font-size: 11px;

}


.mi-detail-row:last-child {

    border-bottom: 0;

}


.mi-detail-row > span:first-child {

    color: #8290a0;

}


.mi-detail-row strong {

    color: #2c4662;

    text-align: right;

    font-weight: 850;

}


/* =========================================================
   STATUS PILLS
   ========================================================= */

.mi-status-pill {

    display: inline-flex;

    align-items: center;

    padding:
        5px
        9px;

    border-radius: 20px;

    font-size: 9px;

    font-weight: 850;

}


.mi-status-pill.requested {

    background: #fff3d9;

    color: #a76d00;

}


.mi-status-pill.accepted {

    background: #dcfce7;

    color: #15803d;

}


/* =========================================================
   WAITING MESSAGE
   ========================================================= */

.mi-waiting-message {

    margin-top: 17px;

    padding: 13px;

    border:
        1px
        solid
        #cdeef1;

    border-radius: 9px;

    background: #effbfc;

    color: #4b7580;

    text-align: center;

    font-size: 10px;

}


/* =========================================================
   RIGHT INFO CARD
   ========================================================= */

.mi-sidebar {

    width: 100%;

    display: flex;

    flex-direction: column;

    gap: 13px;

    position: sticky;

    top: 95px;

}


.mi-side-card {

    width: 100%;

    padding: 18px;

    border:
        1px
        solid
        #dce5ee;

    border-radius: 15px;

    background: #ffffff;

    box-shadow:
        0
        7px
        24px
        rgba(28,89,131,.055);

}


/* =========================================================
   SIDE TITLE
   ========================================================= */

.mi-side-title {

    display: flex;

    align-items: center;

    gap: 7px;

    margin-bottom: 16px;

    color: #213b58;

    font-size: 13px;

    font-weight: 850;

}


.mi-side-title-icon {

    width: 25px;

    height: 25px;

    display: inline-flex;

    align-items: center;

    justify-content: center;

    border-radius: 7px;

    background: #e9f9ef;

    color: #159447;

    font-size: 11px;

}


.mi-side-title-icon.purple {

    background: #eee7ff;

    color: #6254ed;

}


.mi-side-label {

    margin-bottom: 10px;

    color: #5146e5;

    font-size: 9px;

    font-weight: 900;

    letter-spacing: 1.7px;

}


/* =========================================================
   BOOKING PROGRESS
   ========================================================= */

.mi-progress {

    display: flex;

    flex-direction: column;

}


.mi-progress-item {

    display: flex;

    align-items: center;

    gap: 10px;

}


.mi-progress-number {

    width: 29px;

    height: 29px;

    min-width: 29px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    background: #edf1f5;

    color: #8493a3;

    font-size: 10px;

    font-weight: 900;

}


.mi-progress-item.active
.mi-progress-number {

    color: #ffffff;

    background:
        linear-gradient(
            135deg,
            #6254ed,
            #765ff0
        );

}


.mi-progress-item.done
.mi-progress-number {

    background: #dcfce7;

    color: #15803d;

}


.mi-progress-item > div:last-child {

    display: flex;

    flex-direction: column;

}


.mi-progress-item strong {

    color: #203b58;

    font-size: 10px;

    font-weight: 900;

}


.mi-progress-item small {

    margin-top: 3px;

    color: #8b99a8;

    font-size: 8px;

}


.mi-progress-line {

    width: 1px;

    height: 19px;

    margin-left: 14px;

    background: #dfe5ec;

}


.mi-progress-line.active {

    background: #6254ed;

}


/* =========================================================
   STUDENT SIDE CARD
   ========================================================= */

.mi-student-profile {

    display: flex;

    align-items: center;

    gap: 10px;

}


.mi-student-avatar {

    width: 40px;

    height: 40px;

    min-width: 40px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 11px;

    background:
        linear-gradient(
            135deg,
            #6254ed,
            #7965f2
        );

    color: #ffffff;

    font-size: 11px;

    font-weight: 850;

}


.mi-student-name {

    color: #233c58;

    font-size: 11px;

    font-weight: 900;

}


.mi-student-id {

    margin-top: 4px;

    color: #8795a6;

    font-size: 9px;

}


/* =========================================================
   BOOKED SLOTS
   ========================================================= */

.mi-booked-section {

    width: 100%;

    margin-top: 20px;

    padding: 21px;

    border:
        1px
        solid
        #dce5ee;

    border-radius: 16px;

    background: #ffffff;

    box-shadow:
        0
        7px
        24px
        rgba(28,89,131,.055);

    overflow: hidden;

}


.mi-booked-section-header {

    display: flex;

    align-items: flex-end;

    justify-content: space-between;

    gap: 18px;

    margin-bottom: 15px;

}


.mi-booked-heading-group {

    min-width: 0;

}


.mi-booked-title-row {

    display: flex;

    align-items: center;

    gap: 9px;

    margin-top: 4px;

}


.booked-section-title {

    margin-bottom: 0;

}


.mi-booked-section-subtitle {

    margin:
        6px
        0
        0;

    color: #7d899b;

    font-size: 10px;

    line-height: 1.5;

}


.mi-booked-horizontal {

    width: 100%;

    display: flex;

    flex-wrap: nowrap;

    gap: 14px;

    overflow-x: auto;

    overflow-y: hidden;

    padding:
        3px
        3px
        11px;

    scrollbar-width: none;

    -ms-overflow-style: none;

}


.mi-booked-horizontal::-webkit-scrollbar {

    width: 0 !important;

    height: 0 !important;

    display: none !important;

}


.mi-booked-item {

    width: 285px;

    min-width: 285px;

    max-width: 285px;

    min-height: 185px;

    flex:
        0
        0
        285px;

    padding: 15px;

    border:
        1px
        solid
        #dce4ed;

    border-top:
        3px
        solid
        #6254ed;

    border-radius: 13px;

    background:
        linear-gradient(
            145deg,
            #ffffff,
            #faf9ff
        );

}


.mi-booked-top {

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 10px;

}


.mi-booked-date {

    color: #6254ed;

    font-size: 10px;

    font-weight: 850;

}


.mi-booked-time {

    margin-top: 8px;

    color: #243e5a;

    font-size: 17px;

    font-weight: 900;

}


.mi-booked-type {

    min-height: 30px;

    margin-top: 7px;

    color: #63768b;

    font-size: 10px;

    line-height: 1.45;

}


.mi-booked-trainer {

    margin-top: 9px;

    color: #7d8a9c;

    font-size: 9px;

}


.mi-booked-trainer i {

    margin-right: 5px;

    color: #6254ed;

}


/* =========================================================
   SPINNER
   ========================================================= */

.spinning {

    display: inline-block;

    animation:
        c360-booking-spin
        1s
        linear
        infinite;

}


@keyframes c360-booking-spin {

    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }

}


/* =========================================================
   MOBILE SIDEBAR
   ========================================================= */

.c360-sidebar-overlay {

    display: none;

}


@media (max-width: 900px) {

    .c360-left-sidebar {

        position: fixed !important;

        left: 0;

        top: 0;

        bottom: 0;

        width: 285px !important;

        min-width: 285px !important;

        max-width: 285px !important;

        transform:
            translateX(-105%);

        z-index: 10000;

        box-shadow:
            8px
            0
            28px
            rgba(25,43,60,.30);

    }


    .campus360-booking.sidebar-open
    .c360-left-sidebar {

        transform:
            translateX(0);

    }


    .campus360-booking.sidebar-closed
    .c360-left-sidebar {

        transform:
            translateX(-105%);

    }


    .c360-sidebar-overlay {

        position: fixed;

        inset: 0;

        z-index: 9990;

        display: block;

        background:
            rgba(15,28,45,.38);

    }


    .campus360-booking.sidebar-closed
    .c360-sidebar-overlay {

        display: none;

    }


    .c360-right-page {

        left: 0 !important;

        width: 100vw !important;

    }


    .mi-layout {

        grid-template-columns: 1fr;

    }


    .mi-sidebar {

        position: static;

        display: grid;

        grid-template-columns:
            repeat(
                2,
                minmax(0,1fr)
            );

    }

}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 1100px) {

    .mi-layout {

        grid-template-columns:
            minmax(0,1fr)
            275px;

    }


    .mi-type-grid {

        grid-template-columns:
            repeat(
                2,
                minmax(0,1fr)
            );

    }

}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 650px) {

    .c360-topbar {

        height: 68px;

        min-height: 68px;

        padding:
            0
            11px;

    }


    .c360-page-heading {

        display: none;

    }


    .c360-topbar-right {

        gap: 5px;

    }


    .c360-top-student-info,
    .c360-top-chevron {

        display: none;

    }


    .c360-top-student {

        padding-left: 4px;

    }


    .c360-top-icon {

        width: 37px;

        height: 37px;

        min-width: 37px;

    }


    .c360-top-avatar {

        width: 37px;

        height: 37px;

        min-width: 37px;

    }


    .c360-page-content {

        padding:
            16px
            10px
            45px;

    }


    .mi-hero {

        min-height: 160px;

        padding:
            25px
            20px;

    }


    .mi-hero-icon {

        display: none;

    }


    .mi-hero-content h1 {

        font-size: 27px;

    }


    .mi-hero-content p {

        font-size: 12px;

    }


    .mi-main-card {

        padding: 18px;

    }


    .mi-sidebar {

        display: block;

    }


    .mi-type-grid {

        grid-template-columns: 1fr;

    }


    .mi-time-grid {

        grid-template-columns: 1fr;

    }


    .mi-section-top {

        align-items: flex-start;

        flex-direction: column;

    }


    .mi-submit-area {

        justify-content: stretch;

    }


    .mi-primary-btn {

        width: 100%;

        min-width: 0;

    }

}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 480px) {

    .c360-notification-button {

        display: none;

    }


    .c360-menu-button {

        width: 38px;

        height: 38px;

        min-width: 38px;

    }


    .c360-menu-button span {

        width: 17px;

    }


    .mi-hero {

        padding:
            24px
            18px;

    }


    .mi-hero-content h1 {

        font-size: 24px;

    }


    .mi-booked-section {

        padding: 16px;

    }


    .mi-booked-item {

        width: 265px;

        min-width: 265px;

        flex-basis: 265px;

    }

}


/* =========================================================
   FINAL HERO OVERRIDE
   EXACT SAME DARK PURPLE AS LEFT SIDEBAR
   ========================================================= */

.campus360-booking .mi-hero {

    background:
        linear-gradient(
            180deg,
            #130d2f 0%,
            #160d38 48%,
            #100a29 100%
        ) !important;

    border:
        1px
        solid
        #2d2157 !important;

    color:
        #ffffff !important;

    box-shadow:
        0
        12px
        28px
        rgba(19,13,47,.22) !important;

}


