.campus360-booking .c360-topbar {

    background:
        #ffffff !important;

}


/* =========================================================
   FINAL DARK PURPLE SIDEBAR
   ========================================================= */

.campus360-booking .c360-left-sidebar {

    background:
        linear-gradient(
            180deg,
            #130d2f 0%,
            #160d38 48%,
            #100a29 100%
        ) !important;

    border-right:
        1px
        solid
        #2d2157 !important;

}


/* =========================================================
   FINAL FULL VIEW
   ========================================================= */

.campus360-booking {

    margin-top: 0 !important;

