    max-width: none !important;

}


body:has(.campus360-booking) > header,
body:has(.campus360-booking) > nav {

    display: none !important;

}


/* =========================================================
   FINAL SCROLLBAR HIDE
   SCROLLING STILL WORKS
   ========================================================= */

.campus360-booking .c360-right-page,
.campus360-booking .c360-sidebar-nav,
.campus360-booking .mi-booked-horizontal {

