}


.campus360-booking .c360-right-page::-webkit-scrollbar,
.campus360-booking .c360-sidebar-nav::-webkit-scrollbar,
.campus360-booking .mi-booked-horizontal::-webkit-scrollbar {

    width: 0 !important;

    height: 0 !important;

    display: none !important;

}
/* =========================================================
   FINAL MOCK INTERVIEW HERO
   DARK PURPLE - #351A61
   ========================================================= */

.campus360-booking .mi-hero {

    position: relative !important;

    z-index: 1 !important;

    background:
        linear-gradient(
            135deg,
            #241044 0%,
            #351A61 52%,
            #45206D 100%
        ) !important;

    border:
        1px solid #5A357D !important;

    color:
        #ffffff !important;

    box-shadow:
        0
        12px
        30px
        rgba(53,26,97,.22) !important;

}


/* Decorative circle */

.campus360-booking .mi-hero::after {

    background:
        rgba(196,181,253,.10) !important;

}


/* Hero icon */

.campus360-booking .mi-hero-icon {

    background:
        rgba(124,58,237,.18) !important;

    color:
        #C4B5FD !important;

}


/* Eyebrow */

.campus360-booking .mi-hero-eyebrow {

    color:
        #DCCBFF !important;

}


/* Hero title */

.campus360-booking .mi-hero-content h1 {

    color:
        #FFFFFF !important;

}


/* Hero description */

