        #FFFFFF !important;

}


/* =========================================================
   KEEP LEFT SIDEBAR DARK PURPLE
   ========================================================= */

.campus360-booking .c360-left-sidebar {

    background:
        linear-gradient(
            180deg,
            #130D2F 0%,
            #160D38 48%,
            #100A29 100%
        ) !important;

    border-right:
        1px solid #2D2157 !important;

}

sp_widget.script:
(function() {

    var AVAIL_TABLE = 'x_snc_campus360_trainer_interview_availability';
    var REQUEST_TABLE = 'x_snc_campus360_mock_interview_slot_request';
    var TRAINER_REQUEST_TABLE = 'x_snc_campus360_mock_interview_request_trainer';
    var MOCK_TABLE = 'x_snc_campus360_mock_interview';
    var STUDENT_TABLE = 'x_snc_campus360_student_master';
    var NOTIFICATION_TABLE = 'x_snc_campus360_student_notification';

    data.error = '';
    data.success = '';
    data.interviewTypes = [];
    data.slots = [];
    data.bookedSlots = [];
    data.student = {
        sys_id: '',
        studentId: '',
        name: ''
    };
    data.currentRequest = null;


    /* ============================================================
       CHOICE HELPERS
       ============================================================ */

    function getChoiceValueByLabel(tableName, fieldName, label) {

        var choice = new GlideRecord('sys_choice');

        choice.addQuery('name', tableName);
        choice.addQuery('element', fieldName);
        choice.addQuery('label', label);
        choice.addQuery('inactive', false);
        choice.setLimit(1);
        choice.query();

        if (choice.next()) {
            return String(choice.getValue('value'));
        }

        var temp = new GlideRecord(tableName);

        if (!temp.isValid() || !temp.isValidField(fieldName)) {
            return '';
        }

        try {

            temp.initialize();

            var el = temp.getElement(fieldName);

            if (el && el.getChoices) {

                var vals = el.getChoices();

                for (var i = 0; i < vals.length; i++) {

                    var val = String(vals[i]);

                    temp.setValue(fieldName, val);

                    var display = '';

                    try {
                        display = String(el.getChoiceValue());
                    } catch (ignore1) {
                        display = String(
                            temp.getDisplayValue(fieldName)
                        );
                    }

                    if (
                        display.toLowerCase() ===
                        String(label).toLowerCase()
                    ) {
                        return val;
                    }
                }
            }

        } catch (ignore2) {}

        return '';
    }


    function setChoiceByLabel(gr, fieldName, label) {

        if (!gr || !gr.isValidField(fieldName)) {
            return false;
        }

        var value = getChoiceValueByLabel(
            gr.getTableName(),
            fieldName,
            label
        );

        if (!value) {
            return false;
        }

        gr.setValue(fieldName, value);

        return String(
            gr.getValue(fieldName)
        ) === value;
    }


    function getChoiceList(tableName, fieldName) {

        var result = [];

        var choice = new GlideRecord('sys_choice');

        choice.addQuery('name', tableName);
        choice.addQuery('element', fieldName);
        choice.addQuery('inactive', false);
        choice.orderBy('sequence');
        choice.query();

        while (choice.next()) {

            result.push({
                value: String(
                    choice.getValue('value')
                ),
                label: String(
                    choice.getValue('label')
                )
            });

        }

        return result;
    }


    /* ============================================================
       TIME FORMATTER
       ============================================================ */

    function formatTime12(value) {

        var raw =
            String(value || '').trim();

        if (!raw) {
            return '';
        }

        if (raw.indexOf('T') >= 0) {

            raw =
                raw.substring(
                    raw.lastIndexOf('T') + 1
                );

        } else if (raw.indexOf(' ') >= 0) {

            var spaceParts =
                raw.split(/\s+/);

            raw =
                spaceParts[
                    spaceParts.length - 1
                ];

        }

        var timeMatch =
            raw.match(
                /(\d{1,2}):(\d{2})(?::(\d{2}))?/
            );

        if (!timeMatch) {
            return raw;
        }

        var hour =
            parseInt(
                timeMatch[1],
                10
            );

        var minute =
            parseInt(
                timeMatch[2],
                10
            );

        if (
            isNaN(hour) ||
            isNaN(minute)
        ) {
            return raw;
        }

        hour =
            hour % 24;

        var ampm =
            hour >= 12
                ? 'PM'
                : 'AM';

        var hour12 =
            hour % 12;

        if (hour12 === 0) {
            hour12 = 12;
        }

        var minuteText =
            minute < 10
                ? '0' + minute
                : String(minute);

        return (
            hour12 +
            ':' +
            minuteText +
            ' ' +
            ampm
        );
    }


    function formatTimeRange(
        startTime,
        endTime
    ) {

        return (
            formatTime12(startTime) +
            ' - ' +
            formatTime12(endTime)
        );
    }


    /* ============================================================
       DATE FORMATTER
       ============================================================ */

    function formatDateDisplay(
        dateValue
    ) {

        var raw =
            String(dateValue || '');

        if (!raw) {
            return '';
        }

        var p =
            raw.split('-');

        if (p.length !== 3) {
            return raw;
        }

        var months = [
            'Jan',
            'Feb',
            'Mar',
            'Apr',
            'May',
            'Jun',
            'Jul',
            'Aug',
            'Sep',
            'Oct',
            'Nov',
            'Dec'
        ];

        var year =
            p[0];

        var month =
            parseInt(
                p[1],
                10
            );

        var day =
            parseInt(
                p[2],
                10
            );

        if (
            isNaN(month) ||
            isNaN(day)
        ) {
            return raw;
        }

        return (
            (day < 10
                ? '0' + day
                : day) +
            ' ' +
            months[month - 1] +
            ' ' +
            year
        );
    }


    function validDateString(
        value
    ) {

        var raw =
            String(value || '');

        if (
            !/^\d{4}-\d{2}-\d{2}$/.test(
                raw
            )
        ) {
            return false;
        }

        var p =
            raw.split('-');

        var year =
            parseInt(
                p[0],
                10
            );

        var month =
            parseInt(
                p[1],
                10
            );

        var day =
            parseInt(
                p[2],
                10
            );

        if (
            month < 1 ||
            month > 12
        ) {
            return false;
        }

        if (
            day < 1 ||
            day > 31
        ) {
            return false;
        }

        return true;
    }


    /* ============================================================
       STUDENT
       ============================================================ */

    function resolveStudent() {

        var userId =
            gs.getUserID();

        var user =
            new GlideRecord('sys_user');

        if (
            userId &&
            user.get(userId)
        ) {

            var email =
                String(
                    user.getValue('email') ||
                    ''
                );

            if (email) {

                var studentByEmail =
                    new GlideRecord(
                        STUDENT_TABLE
                    );

                studentByEmail.addQuery(
                    'email',
                    email
                );

                studentByEmail.setLimit(1);
                studentByEmail.query();

                if (
                    studentByEmail.next()
                ) {
                    return studentByEmail;
                }
            }


            var studentByUser =
                new GlideRecord(
                    STUDENT_TABLE
                );

            if (
                studentByUser.isValidField(
                    'user'
                )
            ) {

                studentByUser.addQuery(
                    'user',
                    userId
                );

                studentByUser.setLimit(1);
                studentByUser.query();

                if (
                    studentByUser.next()
                ) {
                    return studentByUser;
                }
            }
        }


        /*
         * Test/development fallback.
         */
        var fallback =
            new GlideRecord(
                STUDENT_TABLE
            );

        if (
            fallback.isValidField(
                'student_id'
            )
        ) {

            fallback.addQuery(
                'student_id',
                'STU_TEST_001'
            );

            fallback.setLimit(1);
            fallback.query();

            if (fallback.next()) {
                return fallback;
            }
        }

        return null;
    }


    function populateStudentData() {

        var student =
            resolveStudent();

        if (!student) {

            data.error =
                'Student record could not be found.';

            return null;
        }

        data.student.sys_id =
            String(
                student.getUniqueValue()
            );

        if (
            student.isValidField(
                'student_id'
            )
        ) {

            data.student.studentId =
                String(
                    student.getValue(
                        'student_id'
                    ) || ''
                );
        }

        if (
            student.isValidField(
                'student_name'
            )
        ) {

            data.student.name =
                String(
                    student.getValue(
                        'student_name'
                    ) || ''
                );

        } else if (
            student.isValidField(
                'name'
            )
        ) {

            data.student.name =
                String(
                    student.getValue(
                        'name'
                    ) || ''
                );

        } else {

            data.student.name =
                String(
                    student.getDisplayValue() ||
                    ''
                );
        }

        return student;
    }


    /* ============================================================
       INTERVIEW TYPES
       ============================================================ */

    function loadInterviewTypes(
        selectedDate
    ) {

        var choices =
            getChoiceList(
                AVAIL_TABLE,
                'interview_type'
            );

        data.interviewTypes =
            [];

        var availableValue =
            getChoiceValueByLabel(
                AVAIL_TABLE,
                'status',
                'Available'
            );

        for (
            var i = 0;
            i < choices.length;
            i++
        ) {

            var choice =
                choices[i];

            var count = 0;

            if (
                selectedDate &&
                availableValue
            ) {

                var gr =
                    new GlideRecord(
                        AVAIL_TABLE
                    );

                gr.addQuery(
                    'available_date',
                    selectedDate
                );

                gr.addQuery(
                    'interview_type',
                    choice.value
                );

                gr.addQuery(
                    'active',
                    true
                );

                gr.addQuery(
                    'status',
                    availableValue
                );

                gr.query();

                while (gr.next()) {
                    count++;
                }
            }

            data.interviewTypes.push({
                value: choice.value,
                label: choice.label,
                count: count
            });

        }
    }


    /* ============================================================
       LOAD AVAILABLE SLOTS
       ============================================================ */

    function loadSlots(
        selectedDate
    ) {

        data.slots = [];

        if (!selectedDate) {
            return;
        }

        if (
            !validDateString(
                selectedDate
            )
        ) {

            data.error =
                'Invalid interview date.';

            return;
        }

        var availableValue =
            getChoiceValueByLabel(
                AVAIL_TABLE,
                'status',
                'Available'
            );

        if (!availableValue) {

            data.error =
                'The Available status choice could not be resolved from Trainer Interview Availability.';

            return;
        }

        var gr =
            new GlideRecord(
                AVAIL_TABLE
            );

        gr.addQuery(
            'available_date',
            selectedDate
        );

        gr.addQuery(
            'active',
            true
        );

        gr.addQuery(
            'status',
            availableValue
        );

        gr.orderBy(
            'start_time'
        );

        gr.query();

        var groups = {};

        while (gr.next()) {

            var dateValue =
                String(
                    gr.getValue(
                        'available_date'
                    ) || ''
                );

            var startValue =
                String(
                    gr.getValue(
                        'start_time'
                    ) || ''
                );

            var endValue =
                String(
                    gr.getValue(
                        'end_time'
                    ) || ''
                );

            var typeValue =
                String(
                    gr.getValue(
                        'interview_type'
                    ) || ''
                );

            var typeLabel =
                String(
                    gr.getDisplayValue(
                        'interview_type'
                    ) || ''
                );

            var skillValue = '';

            if (
                gr.isValidField(
                    'skill_area'
                )
            ) {

                skillValue =
                    String(
                        gr.getValue(
                            'skill_area'
                        ) || ''
                    );
            }

            var skillLabel = '';

            if (
                gr.isValidField(
                    'skill_area'
                )
            ) {

                skillLabel =
                    String(
                        gr.getDisplayValue(
                            'skill_area'
                        ) || ''
                    );
            }

            var key =
                dateValue +
                '|' +
                startValue +
                '|' +
                endValue +
                '|' +
                typeValue +
                '|' +
                skillValue;

            if (!groups[key]) {

                groups[key] = {

                    key: key,

                    date: dateValue,

                    startTime: startValue,

                    endTime: endValue,

                    displayTime:
                        formatTimeRange(
                            startValue,
                            endValue
                        ),

                    interviewType:
                        typeValue,

                    interviewTypeLabel:
                        typeLabel,

                    skillArea:
                        skillValue,

                    skillAreaLabel:
                        skillLabel,

                    trainerCount: 0,

                    availabilityIds: []

                };
            }

            groups[key].trainerCount++;

            groups[key]
                .availabilityIds
                .push(
                    String(
                        gr.getUniqueValue()
                    )
                );
        }


        for (
            var groupKey in groups
        ) {

            if (
                groups.hasOwnProperty(
                    groupKey
                )
            ) {

                data.slots.push(
                    groups[groupKey]
                );
            }
        }
    }


    /* ============================================================
       REQUEST DETAILS
       ============================================================ */

    function getTimingAvailability(
        requestGr
    ) {

        var availabilityId =
            '';

        if (
            requestGr.isValidField(
                'requested_timing'
            ) &&
            requestGr.getValue(
                'requested_timing'
            )
        ) {

            availabilityId =
                String(
                    requestGr.getValue(
                        'requested_timing'
                    )
                );
        }


        if (
            !availabilityId &&
            requestGr.isValidField(
                'selected_availability'
            ) &&
            requestGr.getValue(
                'selected_availability'
            )
        ) {

            availabilityId =
                String(
                    requestGr.getValue(
                        'selected_availability'
                    )
                );
        }


        if (
            !availabilityId &&
            requestGr.isValidField(
                'selected_slot'
            ) &&
            requestGr.getValue(
                'selected_slot'
            )
        ) {

            availabilityId =
                String(
                    requestGr.getValue(
                        'selected_slot'
                    )
                );
        }


        if (!availabilityId) {
            return null;
        }


        var availability =
            new GlideRecord(
                AVAIL_TABLE
            );

        if (
            !availability.get(
                availabilityId
            )
        ) {

            return null;
        }

        return availability;
    }


    function buildRequestData(
        requestGr
    ) {

        var result = {

            requestId:
                String(
                    requestGr.getUniqueValue()
                ),

            requestNumber:
                String(
                    requestGr.getDisplayValue()
                ),

            status:
                String(
                    requestGr.getDisplayValue(
                        'status'
                    ) || ''
                ),

            statusValue:
                String(
                    requestGr.getValue(
                        'status'
                    ) || ''
                ),

            trainerCount: 0,

            trainer: '',

            date: '',

            dateDisplay: '',

            startTime: '',

            endTime: '',

            displayTime: '',

            interviewType: '',

            skillArea: '',

            mockInterviewNumber: '',

            qrUrl: ''

        };


        var availability =
            getTimingAvailability(
                requestGr
            );


        if (availability) {

            result.date =
                String(
                    availability.getValue(
                        'available_date'
                    ) || ''
                );

            result.dateDisplay =
                formatDateDisplay(
                    result.date
                );

            result.startTime =
                String(
                    availability.getValue(
                        'start_time'
                    ) || ''
                );

            result.endTime =
                String(
                    availability.getValue(
                        'end_time'
                    ) || ''
                );

            result.displayTime =
                formatTimeRange(
                    result.startTime,
                    result.endTime
                );

            result.interviewType =
                String(
                    availability.getDisplayValue(
                        'interview_type'
                    ) || ''
                );

            if (
                availability.isValidField(
                    'skill_area'
                )
            ) {

                result.skillArea =
                    String(
                        availability.getDisplayValue(
                            'skill_area'
                        ) || ''
                    );
            }
        }


        /*
         * Find trainer response.
         */
        var child =
            new GlideRecord(
                TRAINER_REQUEST_TABLE
            );

        if (
            child.isValidField(
                'request'
            )
        ) {

            child.addQuery(
                'request',
                requestGr.getUniqueValue()
            );

            child.query();

            while (child.next()) {

                result.trainerCount++;

                var responseLabel =
                    String(
                        child.getDisplayValue(
                            'response'
                        ) || ''
                    );

                if (
                    responseLabel ===
                    'Accepted'
                ) {

                    if (
                        child.isValidField(
                            'trainer'
                        )
                    ) {

                        result.trainer =
                            String(
                                child.getDisplayValue(
                                    'trainer'
                                ) || ''
                            );
                    }
                }
            }
        }


        if (
            !result.trainer &&
            requestGr.isValidField(
                'accepted_trainer'
            )
        ) {

            result.trainer =
                String(
                    requestGr.getDisplayValue(
                        'accepted_trainer'
                    ) || ''
                );
        }


        /*
         * Mock Interview.
         *
         * For accepted/booked interviews,
         * Mock Interview is the preferred source
         * for the actual scheduled date/time.
         */
        if (
            requestGr.isValidField(
                'mock_interview'
            ) &&
            requestGr.getValue(
                'mock_interview'
            )
        ) {

            var mock =
                new GlideRecord(
                    MOCK_TABLE
                );

            if (
                mock.get(
                    requestGr.getValue(
                        'mock_interview'
                    )
                )
            ) {

                result.mockInterviewNumber =
                    String(
                        mock.getDisplayValue() ||
                        ''
                    );


                if (
                    mock.isValidField(
                        'interview_date'
                    )
                ) {

                    var mockDate =
                        String(
                            mock.getValue(
                                'interview_date'
                            ) || ''
                        );

                    if (mockDate) {

                        result.date =
                            mockDate;

                        result.dateDisplay =
                            formatDateDisplay(
                                mockDate
                            );
                    }
                }


                if (
                    mock.isValidField(
                        'start_time'
                    )
                ) {

                    result.startTime =
                        String(
                            mock.getValue(
                                'start_time'
                            ) || ''
                        );
                }


                if (
                    mock.isValidField(
                        'end_time'
                    )
                ) {

                    result.endTime =
                        String(
                            mock.getValue(
                                'end_time'
                            ) || ''
                        );
                }


                if (
                    result.startTime ||
                    result.endTime
                ) {

                    result.displayTime =
                        formatTimeRange(
                            result.startTime,
                            result.endTime
                        );
                }


                if (
                    mock.isValidField(
                        'interview_type'
                    )
                ) {

                    result.interviewType =
                        String(
                            mock.getDisplayValue(
                                'interview_type'
                            ) ||
                            mock.getValue(
                                'interview_type'
                            ) ||
                            result.interviewType ||
                            ''
                        );
                }


                if (
                    mock.isValidField(
                        'trainer_reference'
                    )
                ) {

                    result.trainer =
                        String(
                            mock.getDisplayValue(
                                'trainer_reference'
                            ) ||
                            result.trainer ||
                            ''
                        );

                } else if (
                    mock.isValidField(
                        'trainer'
                    )
                ) {

                    result.trainer =
                        String(
                            mock.getDisplayValue(
                                'trainer'
                            ) ||
                            result.trainer ||
                            ''
                        );
                }


                if (
                    mock.isValidField(
                        'qr_url'
                    )
                ) {

                    result.qrUrl =
                        String(
                            mock.getValue(
                                'qr_url'
                            ) || ''
                        );

                } else if (
                    mock.isValidField(
                        'qr_code'
                    )
                ) {

                    result.qrUrl =
                        String(
                            mock.getValue(
                                'qr_code'
                            ) || ''
                        );
                }
            }
        }


        return result;
    }


    /* ============================================================
       LATEST REQUEST
       ============================================================ */

    function loadLatestRequest(
        studentSysId
    ) {

        var result = null;

        var gr =
            new GlideRecord(
                REQUEST_TABLE
            );

        gr.addQuery(
            'student',
            studentSysId
        );

        gr.orderByDesc(
            'sys_created_on'
        );

        gr.setLimit(1);
        gr.query();

        if (gr.next()) {

            result =
                buildRequestData(
                    gr
                );
        }

        data.currentRequest =
            result;

        return result;
    }


    /* ============================================================
       BOOKED SLOTS
       ============================================================ */

    function loadBookedSlots(
        studentSysId
    ) {

        data.bookedSlots =
            [];

        var acceptedValue =
            getChoiceValueByLabel(
                REQUEST_TABLE,
                'status',
                'Accepted'
            );

        var completedValue =
            getChoiceValueByLabel(
                REQUEST_TABLE,
                'status',
                'Completed'
            );

        var statusValues =
            [];

        if (acceptedValue) {
            statusValues.push(
                acceptedValue
            );
        }

        if (completedValue) {
            statusValues.push(
                completedValue
            );
        }

        if (
            statusValues.length === 0
        ) {
            return;
        }


        var gr =
            new GlideRecord(
                REQUEST_TABLE
            );

        gr.addQuery(
            'student',
            studentSysId
        );

        gr.addQuery(
            'status',
            'IN',
            statusValues.join(',')
        );

        gr.orderByDesc(
            'sys_created_on'
        );

        gr.query();


        while (gr.next()) {

            var item =
                buildRequestData(
                    gr
                );

            item.requestId =
                String(
                    gr.getUniqueValue()
                );

            data.bookedSlots.push(
                item
            );
        }
    }


    /* ============================================================
       SUBMIT REQUEST
       ============================================================ */

    function submitRequest(
        studentSysId
    ) {

        var selectedDate =
            String(
                input.selectedDate ||
                ''
            );

        var selectedAvailabilityId =
            String(
                input.selectedAvailabilityId ||
                ''
            );


        if (
            !validDateString(
                selectedDate
            )
        ) {

            data.error =
                'Please select a valid interview date.';

            return;
        }


        if (!selectedAvailabilityId) {

            data.error =
                'Please select an available time slot.';

            return;
        }


        var selected =
            new GlideRecord(
                AVAIL_TABLE
            );

        if (
            !selected.get(
                selectedAvailabilityId
            )
        ) {

            data.error =
                'The selected availability record no longer exists. Please refresh the date and select an available slot again.';

            return;
        }


        var availableValue =
            getChoiceValueByLabel(
                AVAIL_TABLE,
                'status',
                'Available'
            );

        if (!availableValue) {

            data.error =
                'Available status could not be resolved.';

            return;
        }


        var dbDate =
            String(
                selected.getValue(
                    'available_date'
                ) || ''
            );

        if (
            dbDate !== selectedDate
        ) {

            data.error =
                'The selected date does not match the availability record. Please refresh and select the slot again.';

            return;
        }


        if (
            String(
                selected.getValue(
                    'active'
                )
            ) !== '1' &&
            String(
                selected.getValue(
                    'active'
                )
            ) !== 'true'
        ) {

            data.error =
                'This availability is no longer active. Please refresh the date and select an available slot again.';

            return;
        }


        if (
            String(
                selected.getValue(
                    'status'
                )
            ) !==
            String(
                availableValue
            )
        ) {

            data.error =
                'This availability is no longer available. Please refresh the date and select another available slot.';

            return;
        }


        var startTime =
            String(
                selected.getValue(
                    'start_time'
                ) || ''
            );

        var endTime =
            String(
                selected.getValue(
                    'end_time'
                ) || ''
            );

        var interviewType =
            String(
                selected.getValue(
                    'interview_type'
                ) || ''
            );

        var skillArea = '';

        if (
            selected.isValidField(
                'skill_area'
            )
        ) {

            skillArea =
                String(
                    selected.getValue(
                        'skill_area'
                    ) || ''
                );
        }


        /*
         * Find every trainer with this exact slot.
         */
        var matchingAvailabilities =
            new GlideRecord(
                AVAIL_TABLE
            );

        matchingAvailabilities.addQuery(
            'available_date',
            selectedDate
        );

        matchingAvailabilities.addQuery(
            'start_time',
            startTime
        );

        matchingAvailabilities.addQuery(
            'end_time',
            endTime
        );

        matchingAvailabilities.addQuery(
            'interview_type',
            interviewType
        );


        if (
            selected.isValidField(
                'skill_area'
            ) &&
            skillArea
        ) {

            matchingAvailabilities.addQuery(
                'skill_area',
                skillArea
            );
        }


        matchingAvailabilities.addQuery(
            'active',
            true
        );

        matchingAvailabilities.addQuery(
            'status',
            availableValue
        );

        matchingAvailabilities.query();


        var availabilityIds =
            [];

        var trainerIds =
            [];


        while (
            matchingAvailabilities.next()
        ) {

            availabilityIds.push(
                String(
                    matchingAvailabilities
                        .getUniqueValue()
                )
            );


            if (
                matchingAvailabilities
                    .isValidField('trainer') &&
                matchingAvailabilities
                    .getValue('trainer')
            ) {

                trainerIds.push(
                    String(
                        matchingAvailabilities
                            .getValue('trainer')
                    )
                );
            }
        }


        if (
            availabilityIds.length === 0
        ) {

            data.error =
                'This availability is no longer available. Please refresh the date and select another available slot.';

            return;
        }


        /*
         * Duplicate request check.
         */
        var requestedValue =
            getChoiceValueByLabel(
                REQUEST_TABLE,
                'status',
                'Requested'
            );

        var acceptedValue =
            getChoiceValueByLabel(
                REQUEST_TABLE,
                'status',
                'Accepted'
            );


        var existing =
            new GlideRecord(
                REQUEST_TABLE
            );

        existing.addQuery(
            'student',
            studentSysId
        );

        var statusQuery =
            [];


        if (requestedValue) {
            statusQuery.push(
                requestedValue
            );
        }

        if (acceptedValue) {
            statusQuery.push(
                acceptedValue
            );
        }


        if (
            statusQuery.length > 0
        ) {

            existing.addQuery(
                'status',
                'IN',
                statusQuery.join(',')
            );
        }


        existing.query();


        while (existing.next()) {

            var existingAvailability =
                getTimingAvailability(
                    existing
                );


            if (existingAvailability) {

                var existingDate =
                    String(
                        existingAvailability
                            .getValue(
                                'available_date'
                            ) || ''
                    );

                var existingStart =
                    String(
                        existingAvailability
                            .getValue(
                                'start_time'
                            ) || ''
                    );

                var existingEnd =
                    String(
                        existingAvailability
                            .getValue(
                                'end_time'
                            ) || ''
                    );

                var existingType =
                    String(
                        existingAvailability
                            .getValue(
                                'interview_type'
                            ) || ''
                    );


                if (
                    existingDate === selectedDate &&
                    existingStart === startTime &&
                    existingEnd === endTime &&
                    existingType === interviewType
                ) {

                    data.error =
                        'You already have a request for this exact interview slot.';

                    return;
                }
            }
        }


        /*
         * Create parent request.
         */
        var request =
            new GlideRecord(
                REQUEST_TABLE
            );

        request.initialize();


        request.setValue(
            'student',
            studentSysId
        );


        if (
            request.isValidField(
                'requested_timing'
            )
        ) {

            request.setValue(
                'requested_timing',
                selectedAvailabilityId
            );
        }


        if (
            request.isValidField(
                'selected_availability'
            )
        ) {

            request.setValue(
                'selected_availability',
                selectedAvailabilityId
            );
        }


        if (
            request.isValidField(
                'requested_date'
            )
        ) {

            request.setValue(
                'requested_date',
                selectedDate
            );
        }


        if (
            request.isValidField(
                'selected_date'
            )
        ) {

            request.setValue(
                'selected_date',
                selectedDate
            );
        }


        setChoiceByLabel(
            request,
            'status',
            'Requested'
        );


        if (
            request.isValidField(
                'requested_on'
            )
        ) {

            request.setValue(
                'requested_on',
                new GlideDateTime().getValue()
            );
        }


        if (
            request.isValidField(
                'notes'
            ) &&
            input.notes
        ) {

            request.setValue(
                'notes',
                String(
                    input.notes
                )
            );
        }


        var requestSysId =
            request.insert();


        if (!requestSysId) {

            data.error =
                'The mock interview request could not be created.';

            return;
        }


        /*
         * Create trainer request rows.
         */
        var childCount =
            0;


        for (
            var i = 0;
            i < trainerIds.length;
            i++
        ) {

            var trainerId =
                trainerIds[i];


            var child =
                new GlideRecord(
                    TRAINER_REQUEST_TABLE
                );

            child.initialize();


            if (
                child.isValidField(
                    'request'
                )
            ) {

                child.setValue(
                    'request',
                    requestSysId
                );
            }


            if (
                child.isValidField(
                    'trainer'
                )
            ) {

                child.setValue(
                    'trainer',
                    trainerId
                );
            }


            setChoiceByLabel(
                child,
                'response',
                'Pending'
            );


            if (
                child.isValidField(
                    'notification_sent'
                )
            ) {

                child.setValue(
                    'notification_sent',
                    false
                );
            }


            child.insert();

            childCount++;
        }


        /*
         * Return request.
         */
        var freshRequest =
            new GlideRecord(
                REQUEST_TABLE
            );


        if (
            freshRequest.get(
                requestSysId
            )
        ) {

            data.currentRequest =
                buildRequestData(
                    freshRequest
                );

            data.currentRequest.trainerCount =
                childCount;
        }


        data.success =
            'Your mock interview request has been sent to ' +
            childCount +
            ' available trainer(s).';


        data.slots = [];

        loadInterviewTypes(
            selectedDate
        );

        loadSlots(
            selectedDate
        );

        loadBookedSlots(
            studentSysId
        );
    }


    /* ============================================================
       POLL REQUEST
       ============================================================ */

    function pollRequest(
        studentSysId
    ) {

        var requestId =
            String(
                input.requestId ||
                ''
            );


        if (!requestId) {

            loadLatestRequest(
                studentSysId
            );

            return;
        }


        var request =
            new GlideRecord(
                REQUEST_TABLE
            );


        request.addQuery(
            'sys_id',
            requestId
        );

        request.addQuery(
            'student',
            studentSysId
        );

        request.setLimit(1);
        request.query();


        if (
            request.next()
        ) {

            data.currentRequest =
                buildRequestData(
                    request
                );

        } else {

            data.error =
                'The mock interview request could not be found.';
        }


        loadBookedSlots(
            studentSysId
        );
    }


    /* ============================================================
       INITIAL LOAD
       ============================================================ */

    var student =
        populateStudentData();


    if (!student) {
        return;
    }


    var selectedDate =
        String(
            input &&
            input.selectedDate
                ? input.selectedDate
                : ''
        );


    if (
        input &&
        input.action === 'load'
    ) {

        loadInterviewTypes(
            selectedDate
        );

        loadSlots(
            selectedDate
        );

        loadBookedSlots(
            student.getUniqueValue()
        );


    } else if (
        input &&
        input.action === 'submit'
    ) {

        submitRequest(
            student.getUniqueValue()
        );


    } else if (
        input &&
        input.action === 'poll'
    ) {

        pollRequest(
            student.getUniqueValue()
        );


    } else {

        loadInterviewTypes('');

        loadSlots('');

        loadBookedSlots(
            student.getUniqueValue()
        );
    }

})();

data.aiWidget = $sp.getWidget('campus360_ai_assistant');
